import pyomo.environ as pyo

DATA = {
    "n": 5,                          # number of years
    "production": [10, 12, 8, 15, 9],  # a_j: jets produced each year
    "k": 3,                          # pilots trained per training jet per year
}


def build_model(data=None):
    d = data or DATA
    n = d["n"]
    a = d["production"]
    k = d["k"]

    model = pyo.ConcreteModel()

    # --- Sets ---
    model.Years = pyo.RangeSet(1, n)

    # --- Variables ---
    def combat_bounds(m, j):
        return (0, a[j - 1])

    def training_bounds(m, j):
        return (0, a[j - 1])

    model.combat = pyo.Var(
        model.Years, within=pyo.NonNegativeIntegers, bounds=combat_bounds
    )
    model.training = pyo.Var(
        model.Years, within=pyo.NonNegativeIntegers, bounds=training_bounds
    )
    model.pilots = pyo.Var(model.Years, within=pyo.NonNegativeReals, bounds=(0, None))

    # --- Objective: maximize total combat jets + trained pilots ---
    def obj_rule(m):
        return sum(m.combat[j] + m.pilots[j] for j in m.Years)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # --- Constraints ---

    # Each year's production is fully allocated between combat and training
    def alloc_rule(m, j):
        return m.combat[j] + m.training[j] == a[j - 1]

    model.allocation = pyo.Constraint(model.Years, rule=alloc_rule)

    # Pilots trained each year from training jets
    def pilots_rule(m, j):
        return m.pilots[j] == k * m.training[j]

    model.pilot_training = pyo.Constraint(model.Years, rule=pilots_rule)

    # Enough pilots to operate the combat jets (one pilot per combat jet)
    def sufficiency_rule(m, j):
        return m.pilots[j] >= m.combat[j]

    model.pilot_sufficiency = pyo.Constraint(model.Years, rule=sufficiency_rule)

    return model


